BEGIN;
SELECT fixture_fee(3000);
SET CONSTRAINTS accounting_tournament_fee_commit_capture IMMEDIATE;
SELECT assert_true((fn_accounting_tournament_fee_net_plan(u(3000))->>'net_fee')::numeric=1,'recognition plan reads exact captured fee');
INSERT INTO union_wallet_transactions VALUES(u(3090),u(90),u(99),'rake_wallet','credit','rake',1,transaction_timestamp(),'fee [tournament '||u(3000)||']');
SELECT fn_recognize_accounting_tournament_fees(u(3000),transaction_timestamp(),u(99),u(3090),NULL);
SELECT assert_true(count(*)=1 AND sum(amount)=0.25 AND min(club_id::text)=u(21)::text,'shared writer posts fee commission to original earning club') FROM agent_commissions WHERE source_id IN(SELECT id FROM accounting_tournament_fee_sources WHERE tournament_id=u(3000));
SELECT assert_true(count(*)=1 AND sum(credit)=1,'recognized source posts player stats once') FROM stats_probe WHERE raw_id=u(3001);
SELECT assert_true((fn_recognize_accounting_tournament_fees(u(3000),transaction_timestamp(),u(99),u(3090),NULL)->>'replayed')::boolean AND (SELECT count(*)=1 FROM agent_commissions),'recognition retry cannot duplicate shared commissions');
SELECT fixture_fee(3100,true,1);
SET CONSTRAINTS accounting_tournament_fee_commit_capture IMMEDIATE;
INSERT INTO union_wallet_transactions VALUES(u(3190),u(90),u(99),'rake_wallet','credit','rake',0.99,transaction_timestamp(),'fee [tournament '||u(3100)||']');
SELECT assert_sql_refuses('SELECT fn_recognize_accounting_tournament_fees(u(3100),transaction_timestamp(),u(99),u(3190),NULL)','tournament_fee_union_bank_receipt_mismatch','bank receipt must prove every fee cent');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM accounting_tournament_fee_recognitions WHERE tournament_id=u(3100)),'failed bank proof writes no recognition');
UPDATE union_wallet_transactions SET amount=1 WHERE id=u(3190);
SELECT set_config('fixture.stats_fail',u(3113)::text,true);
SELECT assert_sql_refuses('SELECT fn_recognize_accounting_tournament_fees(u(3100),transaction_timestamp(),u(99),u(3190),NULL)','injected_stats_failure','last player failure aborts all recognition work');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM accounting_tournament_fee_recognitions WHERE tournament_id=u(3100)) AND NOT EXISTS(SELECT 1 FROM agent_commissions WHERE source_id IN(SELECT id FROM accounting_tournament_fee_sources WHERE tournament_id=u(3100))) AND NOT EXISTS(SELECT 1 FROM stats_probe WHERE raw_id=u(3101)),'recognition rollback removes every prior commission and statistic');
SELECT set_config('fixture.stats_fail','',true);
SELECT fn_recognize_accounting_tournament_fees(u(3100),transaction_timestamp(),u(99),u(3190),NULL);
SELECT assert_true(count(*)=3 AND sum(amount)=0.25,'one shared agent can receive all three Spin contributors across clubs') FROM agent_commissions WHERE source_id IN(SELECT id FROM accounting_tournament_fee_sources WHERE tournament_id=u(3100));

SELECT fixture_fee(3200);
SET CONSTRAINTS accounting_tournament_fee_commit_capture IMMEDIATE;
INSERT INTO rake_records(id,tournament_id,is_tournament,club_id,rake_amount,source,metadata,created_at) VALUES(u(3202),u(3200),true,u(99),-1,'fn_unregister_from_tournament',jsonb_build_object('user_id',u(3211),'original_rake_record_ids',jsonb_build_array(u(3201))),transaction_timestamp());
INSERT INTO tournament_unregistration_receipts VALUES(u(3200),u(3211),ARRAY[u(3202)],ARRAY[u(3201)]);
SELECT assert_true((fn_accounting_tournament_fee_net_plan(u(3200))->>'net_fee')::numeric=0,'exact full entry refund removes fee earning');
SELECT fn_recognize_accounting_tournament_fees(u(3200),transaction_timestamp(),u(99),NULL,NULL);
SELECT assert_true(NOT EXISTS(SELECT 1 FROM agent_commissions WHERE source_id IN(SELECT id FROM accounting_tournament_fee_sources WHERE tournament_id=u(3200))) AND (SELECT bool_and(disposition='refunded' AND rake_credit=0) FROM accounting_tournament_recognized_sources WHERE tournament_id=u(3200)),'refunded fee is recorded but earns no commission');
SELECT fixture_fee(3300,true,1);
SET CONSTRAINTS accounting_tournament_fee_commit_capture IMMEDIATE;
INSERT INTO rake_records(id,tournament_id,is_tournament,club_id,rake_amount,source,metadata,created_at) VALUES(u(3303),u(3300),true,u(99),-1,'atomic_cancel_tournament',jsonb_build_object('original_rake_record_id',u(3301)),transaction_timestamp());
INSERT INTO tournament_cancellation_receipts VALUES(u(3300),ARRAY[u(3303)],0,1,1);
SELECT fn_recognize_accounting_tournament_fees(u(3300),transaction_timestamp(),u(99),NULL,NULL);
SELECT assert_true(count(*)=3 AND bool_and(disposition='refunded' AND rake_credit=0),'Spin cancellation reverses all exact contributor sources') FROM accounting_tournament_recognized_sources WHERE tournament_id=u(3300);
SELECT fixture_fee(3400);
SET CONSTRAINTS accounting_tournament_fee_commit_capture IMMEDIATE;
INSERT INTO rake_records(id,tournament_id,is_tournament,club_id,rake_amount,source,metadata,created_at) VALUES(u(3402),u(3400),true,u(99),-0.5,'fn_unregister_from_tournament',jsonb_build_object('user_id',u(3411),'original_rake_record_ids',jsonb_build_array(u(3401))),transaction_timestamp());
SELECT assert_sql_refuses('SELECT fn_accounting_tournament_fee_net_plan(u(3400))','tournament_fee_refund_not_exact_full_sources','unsupported partial fee allocation fails closed');
UPDATE rake_records SET rake_amount=-1 WHERE id=u(3402);
SELECT assert_sql_refuses('SELECT fn_accounting_tournament_fee_net_plan(u(3400))','tournament_fee_refund_receipt_missing','raw negative alone cannot certify a refund');
SELECT count(*) AS native_assertions FROM assertions;
COMMIT;
